# Get all files in downloads directory
all_files = apis.file_system.show_directory(access_token=token, directory_path='~/downloads/', entry_type='files', recursive=False)
print(f"Total files: {len(all_files)}")

# Get details for all files
file_details_map = {}
for i, file_path in enumerate(all_files):
    try:
        info = apis.file_system.show_file(file_path=file_path, access_token=token)
        file_details_map[file_path] = info
        if (i + 1) % 10 == 0:
            print(f"Processed {i + 1} files...")
    except Exception as e:
        print(f"Error getting {file_path}: {e}")

print(f"Successfully retrieved details for {len(file_details_map)} files")
