# I'll get details for all files and organize them by creation date

file_info_list = []

for file_path in files:
    file_details = apis.file_system.show_file(
        access_token=access_token,
        file_path=file_path
    )
    file_info_list.append({
        'path': file_path,
        'filename': file_path.split('/')[-1],
        'created_at': file_details['created_at']
    })

# Print summary
print(f"Total files: {len(file_info_list)}")
print("\nFiles by year:")
years = {}
for info in file_info_list:
    year = info['created_at'][:4]
    if year not in years:
        years[year] = []
    years[year].append(info)

for year in sorted(years.keys()):
    print(f"  {year}: {len(years[year])} files")

