# Now I need to get details for all songs to check their genres
# First, let me collect all song IDs from liked songs, albums, and playlists

all_song_ids = set()

# From liked songs
for song in liked_songs:
    all_song_ids.add(song['song_id'])

# From liked albums
for album in liked_albums:
    for song_id in album['song_ids']:
        all_song_ids.add(song_id)

# From playlists
for playlist in playlists:
    for song_id in playlist['song_ids']:
        all_song_ids.add(song_id)

print(f"Total unique song IDs to check: {len(all_song_ids)}")
print(f"Song IDs: {sorted(all_song_ids)}")

# Get details for the first batch of songs
song_details = {}
for song_id in sorted(all_song_ids)[:10]:
    result = apis.spotify.show_song(access_token=token, song_id=song_id)
    song_details[song_id] = result
    print(f"Song {song_id}: {result}")

# Get details for all songs to check their genre and play count
songs_details = {}
for song_id in sorted(all_song_ids):
    song_detail = apis.spotify.show_song(access_token=token, song_id=song_id)
    songs_details[song_id] = song_detail
    print(f"Song {song_id}: {song_detail.get('title')} - Genre: {song_detail.get('genre')} - Play count: {song_detail.get('play_count')}")

