   "default": null,
   "constraints": []
  },
  {
   "name": "description",
   "type": "string",
   "required": false,
   "description": "Description of or note about the transaction.",
   "default": "",
   "constraints": []
  },
  {
   "name": "payment_card_id",
   "type": "integer",
